 SELECT 'site','site','es-MX','{"headline": "Un poco de desorden. Mucha imaginación.", "intro": "Arte y manualidades para peques con curiosidad. Crea algo especial, descubre algo nuevo y deja que la creatividad marque el camino.", "about": "Adventure Station reúne a niñas y niños para explorar su imaginación con arte y manualidades de temporada.", "promotion": "Haz espacio para la creatividad.", "faqs": [{"question": "¿Para qué edades son los talleres?", "answer": "Consulta el rango de edad recomendado en cada taller."}, {"question": "¿Cómo inscribo a mi peque?", "answer": "Elige un taller y una fecha disponible. Una madre, padre o tutor completa la inscripción y el pago seguro."}], "refundPolicy": "", "supervisionPolicy": "", "pickupPolicy": "", "privacyPolicy": ""}',revision,0,'system:starter-copy' FROM settings WHERE key='site' AND json_extract(value,'$.headline')='A little mess. A lot of imagination.' AND json_extract(value,'$.about')='Adventure Station brings children together to explore their imagination through seasonal arts and crafts.';
